import type { SouthernTone } from '@motivation/shared';

/** Story 442: what a spoken answer can be. */
export type DrillAnswer = SouthernTone | 'repeat' | 'stop';

/**
 * DLR #352: answers are English words for the pitch contour, recognised as `en-US`. Vietnamese tone names
 * failed for a learner's voice — the recogniser hears the learner's tones, so it graded pronunciation.
 */
export const ANSWER_WORDS: Readonly<Record<SouthernTone, string>> = {
    ngang: 'flat',
    huyền: 'falling',
    sắc: 'rising',
    hỏi: 'dipping',
    nặng: 'heavy',
};

/** How Chrome mishears an answer word on the phone ("rising" came back as "raising"); never shown. */
const MISHEARINGS: ReadonlyArray<readonly [string, SouthernTone]> = [['raising', 'sắc']];

const PHRASES: ReadonlyArray<readonly [string, DrillAnswer]> = [
    ...(Object.entries(ANSWER_WORDS) as Array<[SouthernTone, string]>).map(([tone, word]) => [word, tone] as const),
    ...MISHEARINGS,
    ['repeat', 'repeat'],
    ['stop', 'stop'],
];

/** Lowercase NFC words, punctuation dropped, joined by single spaces and padded so phrases match whole. */
function words(text: string): string {
    return ` ${text.normalize('NFC').toLowerCase().replace(/[^\p{L}\p{M}\s]/gu, ' ').split(/\s+/).filter(Boolean).join(' ')} `;
}

/**
 * The answer in what Chrome heard: the first alternative holding an answer word decides; two different
 * answers there is not understood (null), and so is none at all.
 */
export function matchAnswer(alternatives: readonly string[]): DrillAnswer | null {
    for (const alternative of alternatives) {
        const heard = words(alternative);
        const found = new Set(PHRASES.filter(([phrase]) => heard.includes(` ${phrase} `)).map(([, answer]) => answer));
        if (found.size === 1) return [...found][0];
        if (found.size > 1) return null;
    }
    return null;
}
